     1→/**
     2→ * FreeLang StdLib — 통합 인덱스
     3→ *
     4→ * 사용법:
     5→ *   const stdlib = require('freelang-ecosystem/stdlib');
     6→ *   stdlib.math.clamp(5, 0, 10);
     7→ *   stdlib.string.camelCase('hello_world');
     8→ *
     9→ * 모듈별 개별 임포트:
    10→ *   const { math }     = require('freelang-ecosystem/stdlib');
    11→ *   const math         = require('freelang-ecosystem/stdlib/math');
    12→ */
    13→'use strict';
    14→
    15→const math       = require('./math');
    16→const string     = require('./string');
    17→const array      = require('./array');
    18→const functional = require('./functional');
    19→const datetime   = require('./datetime');
    20→
    21→const stdlib = {
    22→  math,
    23→  string,
    24→  array,
    25→  functional,
    26→  datetime,
    27→
    28→  /** 모든 모듈 메타 목록 */
    29→  modules() {
    30→    return [math, string, array, functional, datetime].map(m => ({
    31→      name:    m.name,
    32→      version: m.version,
    33→    }));
    34→  },
    35→
    36→  /** name으로 모듈 조회 */
    37→  get(name) {
    38→    return [math, string, array, functional, datetime]
    39→      .find(m => m.name === name) ?? null;
    40→  },
    41→};
    42→
    43→module.exports = stdlib;
